import type {OutgoingMessage} from './messages.js';

export interface TextMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface ToolCallContent {
  type: 'tool_use';
  toolUseId: string;
  name: string;
  input: Record<string, unknown>;
}

export interface ToolResultContent {
  type: 'tool_result';
  toolUseId: string;
  content: string;
}

export interface ToolUseMessage {
  role: 'assistant';
  content: ToolCallContent[];
}

export interface ToolResultMessage {
  role: 'user';
  content: ToolResultContent[];
}

export type Message = TextMessage | ToolUseMessage | ToolResultMessage;

export interface ToolDefinition {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  promptInstructions?: string;
  examplePrompts?: string[];
}

export interface ToolCall {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export type MessageChunk =
  | {type: 'text'; text: string}
  | {type: 'tool_use'; toolCall: ToolCall}
  | {type: 'tool_result'; clientMessages: OutgoingMessage[]}
  | {type: 'suppress_output'}
  | {type: 'stop'; stopReason: string; usage?: UsageMetadata};

export interface SendMessageParams {
  messages: Message[];
  systemPrompt: string;
  tools?: ToolDefinition[];
  maxTokens?: number;
}

export interface StructuredOutputParams<_T> {
  messages: Message[];
  systemPrompt: string;
  responseSchema: ResponseSchema;
  maxTokens?: number;
}

export interface ResponseSchema {
  type: 'object' | 'array' | 'string' | 'number' | 'boolean';
  properties?: Record<string, ResponseSchema>;
  items?: ResponseSchema;
  required?: string[];
  description?: string;
  enum?: string[];
}

export interface UsageMetadata {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

export interface AIProviderResponse {
  usage?: UsageMetadata;
}

export interface AIProvider {
  sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk>;
  generateStructured<T>(params: StructuredOutputParams<T>): Promise<T>;
}

export class AIError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    // eslint-disable-next-line re-lint/no-flag-params -- public API; splitting AIError is a breaking change (adrs/ADR-006-lint-suppressions.md)
    public readonly retryable: boolean = false
  ) {
    super(message);
    this.name = 'AIError';
  }
}
export interface Logger {
  debug(category: string, message: string, fields?: Record<string, unknown>): void;
  info(category: string, message: string, fields?: Record<string, unknown>): void;
  warn(category: string, message: string, fields?: Record<string, unknown>): void;
  error(category: string, message: string, fields?: Record<string, unknown>): void;
}

const LOG_LEVELS = {DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3} as const;
type LevelName = keyof typeof LOG_LEVELS;

const METHODS = {DEBUG: 'debug', INFO: 'info', WARN: 'warn', ERROR: 'error'} as const;

const resolvedLevel = (() => {
  const env = (process.env.LOG_LEVEL || 'info').toUpperCase();
  return LOG_LEVELS[env as LevelName] ?? LOG_LEVELS.INFO;
})();

export const UNSERIALISABLE = '[unserialisable]';

function emit(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
  // Caller fields are nested under `data`, so one named `severity` cannot overwrite the line's own.
  const line = {
    severity: level,
    message,
    timestamp: new Date().toISOString(),
    category,
    ...(fields ? {data: fields} : {}),
  };

  // ERROR to stderr: a stream that cannot be split by severity cannot be alerted on.
  // eslint-disable-next-line no-console -- the one place this package writes to a stream
  (level === 'ERROR' ? console.error : console.log)(serialise(line));
}

// A throw here would take down the call site being observed, so an unserialisable field costs that field alone.
function serialise(line: Record<string, unknown>): string {
  const whole = probe(() => JSON.stringify(line));
  if (whole.ok) return whole.value;

  // String() runs the caller's toString, so it is attempted inside the probe rather than before it.
  const degraded = probe(() =>
    JSON.stringify({
      severity: line.severity,
      message: String(line.message),
      timestamp: line.timestamp,
      category: String(line.category),
      data: `${UNSERIALISABLE}: ${whole.reason}`,
    })
  );
  if (degraded.ok) return degraded.value;

  // Nothing the caller supplied survives into this one, so it cannot fail in turn.
  return JSON.stringify({
    severity: line.severity,
    message: UNSERIALISABLE,
    timestamp: line.timestamp,
    category: UNSERIALISABLE,
    data: `${UNSERIALISABLE}: ${degraded.reason}`,
  });
}

// A probe, not control flow: it reports what happened rather than branching on a swallowed error.
function probe(run: () => string): {ok: true; value: string} | {ok: false; reason: string} {
  try {
    return {ok: true, value: run()};
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return {ok: false, reason: reason.split('\n')[0]};
  }
}

const consoleLogger: Logger = {
  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('DEBUG', category, message, fields),
  info: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('INFO', category, message, fields),
  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('WARN', category, message, fields),
  error: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('ERROR', category, message, fields),
};

let active: Logger = consoleLogger;

// Process-global by design: every module that logs imports `log` at module scope, so there is one.
export function setLogger(logger?: Logger): void {
  // Handed `log` itself, the delegate below would call itself until the stack ran out, so that reads as none.
  active = logger === undefined || logger === log ? consoleLogger : logger;
}

// The one place a level is tested, so LOG_LEVEL gates a supplied logger exactly as it gates the built-in one.
function dispatch(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
  if (LOG_LEVELS[level] < resolvedLevel) return;

  const delivered = probe(() => {
    active[METHODS[level]](category, message, fields);
    return '';
  });
  if (delivered.ok) return;

  // A supplied logger that throws must not take down the call site it observes, and the line is not dropped.
  probe(() => {
    emit(level, category, message, fields);
    return '';
  });
}

// Delegating rather than reassigned, so a module that imported `log` before the swap still sees it.
export const log: Logger = {
  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('DEBUG', category, message, fields),
  info: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('INFO', category, message, fields),
  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('WARN', category, message, fields),
  error: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('ERROR', category, message, fields),
};
# AGENTS.md

## Context Loading Order

Agents should read files in this order to understand the HAL Engine codebase:

1. **README.md** - Overview, features, quick start, and project structure
2. **package.json** - Dependencies, scripts, tech stack validation
3. **tsconfig.json** - TypeScript configuration and compilation targets
4. **src/index.ts** - Public API exports and module surface
5. **src/config.ts** - Main factory function `createHalEngine()` and configuration schema
6. **src/types/** - Core type definitions (ai.ts, session.ts, messages.ts, auth.ts, sessionStore.ts)
7. **src/providers/** - AI provider implementations (bedrock, vertex, openai, anthropic, mock)
8. **src/infrastructure/** - Support layers (builders, stores, parsers)
9. **src/orchestration/** - Business logic (chatOrchestrator, tools, context management)
10. **src/transport/** - Server setup (Express app, WebSocket, routes)
11. **specs/** - Normative specs (architecture, WebSocket protocol, providers, tool responses)
12. **adrs/** - Architecture Decision Records
13. **docs/** - How-to guides, coding practices, and research spikes under docs/spikes/
14. **.specify/spec.md** - Repo-level system spec (exempt from the spec header table convention)

## Workflow Commands

### Development
```bash
npm run dev          # Start example/server.ts with hot reload (tsx watch)
npm run typecheck    # Run TypeScript type checking without emitting
```

### Building
```bash
npm run build        # Compile TypeScript to dist/ (tsc)
npm start            # Run compiled JavaScript from dist/index.js
```

### Testing
```bash
npm test             # Run Jest test suite
# Tests use ts-jest for TypeScript compilation
# Configuration: jest.config.js
```

### Code Quality
```bash
npm run eslint       # Run ESLint with max-warnings 0 (zero-tolerance)
npm run prettier     # Format all src/**/*.ts with Prettier
npm run prettier:check  # Check formatting without writing
```

### All Checks (Recommended Pre-Commit)
```bash
npm run verify
```

That is the blocking set `.github/workflows/ci.yml`'s `verify` job runs on every
pull request, in the same order, and `scripts/verify-script.test.ts` fails if the
two stop agreeing - so this command cannot quietly become a subset of what CI
demands. Two gates in that job are missing from it because both diff against
`origin/main` and neither runs the same way on a checkout: the spec anchor check
and the changelog check.

Two further CI jobs are worth running locally before a release or a change that
touches packaging: `npm run check:build-chain` (audit and action pins) and
`npm run smoke` (packs the tarball and installs it outside this tree).

## Spec Header Table

Every `specs/*/spec.md` opens with its title, then a two-column header table,
and carries a lead paragraph of prose before its first `##` section:

```markdown
# <spec title>

| Field  | Value                  |
| ------ | ---------------------- |
| Issue  | re-cinq/HALEngine#<n> |
| Status | Draft                  |

<lead paragraph>
```

The lead paragraph does not have to sit immediately after the table: a spec
carrying a metadata block of its own may place that block between the two. What
the convention requires is that prose, rather than a section heading, follows
the header material, and that the prose runs to at least 40 characters -
anything shorter is reported as no lead paragraph at all.

`Issue` names the issue the spec was written against, or `n/a` for the specs
that predate this convention.

`Status` is one of `Draft`, `In Progress` or `Shipped`. It is not a mood, and
it is not a claim about how finished the feature is: it is the spec's own
test-citation coverage. No testable statement cited is `Draft`, some cited is
`In Progress`, all cited is `Shipped`. A spec describing shipped, working
behaviour still reads `Draft` until its statements cite the tests that
validate them.

A spec that should no longer be graded takes a terminal value instead. The
parser buckets roughly sixteen labels into five buckets, and the two terminal
ones skip the coverage check whatever the citation count:

| Written into the spec                                            | Bucket                       |
| ---------------------------------------------------------------- | ---------------------------- |
| `Draft`                                                          | `draft`                      |
| `In Progress`, `In Review`, `Planning`, `WIP`, `Proposed`        | `in-progress`                |
| `Shipped`, `Implemented`, `Complete`, `Accepted`, `Done`, `Live` | `shipped`                    |
| `Retired`, `Superseded`, `Removed`, `Deprecated`, `Obsolete`     | `retired` - skips the check  |
| `Rejected`, `Abandoned`                                          | `rejected` - skips the check |

Prefer the canonical `Draft` / `In Progress` / `Shipped` for a live spec; reach
for `Retired` or `Rejected` rather than leaving a superseded spec to claim a
coverage tier it will never earn.

ADRs do not carry this table. They declare their state as YAML frontmatter
`status:` instead - `accepted` for a decision the code implements, `proposed`
for one it does not. That field does mean maturity, which the spec `Status` row
explicitly does not. The difference is deliberate: ADRs are exempt from the
coverage tier, because asking a decision record to cite a test for every
statement it makes is the wrong ask of a decision record.

`.specify/spec.md` is exempt from this section. It is the repo-level system
spec, it predates the convention, and its content is deliberately frozen -
giving it a header table and a lead paragraph would mean writing new prose into
a file that is meant to stay unchanged. The exemption covers the header table
and the lead paragraph only: the Lore coverage job does scan
`.specify/spec.md`, so link placement still applies to it.

## Spec Test Links

Statements in `specs/*/spec.md` cite their validating test in a trailing
parenthetical at the end of the statement, where a list item counts as one
statement and a paragraph counts per sentence. Tests live beside their source
in this repo, so the path points into `src/`:

```markdown
- All entries within a single assistant response are committed before the next
  user message is processed
  ([validated by: commits every entry before the next user message](../../src/orchestration/chatOrchestrator.test.ts#L42)).
```

The citation carries the test's **name** as well as its line. The name is what the
author cited; the line is a derived pointer, and it goes stale on its own - adding
an import above a suite moves every test below it, and the citation lands on a
different, still-valid declaration without anything noticing. `npm run spec:names`
holds each citation to the test it names, and `npm run spec:names:fix` repoints the
line from the name. The `#Lnn` stays because the lint rule and the coverage job
both index by it; a citation without one marks the whole file covered rather than
one test.

A citation counts as coverage only where it is trailing, and a test link placed
anywhere else in the statement is a misplaced citation rather than a weaker one.
Upstream `check:spec-links` reports it and exits 1, and the coverage job that
consumes these specs records nothing for it - so a spec can read as fully cited while its coverage is
zero. A mid-statement link to something that is not a test file - a script, a
doc, another spec - is ordinary prose, is never reported, and was never coverage
to begin with. A misplaced citation is fixed by moving it to the end of its
statement, never by deleting it.

In a test file the `#Lnn` anchor must land on the `it(`, `test(` or `describe(`
declaration itself - not a blank line, not one holding only closing punctuation,
# CLAUDE.md — HAL Engine

HAL Engine is a TypeScript library that provides a production-ready AI chat server framework with pluggable providers, tool execution, WebSocket streaming, and session management.

## Project context

- **Entry point**: `src/config.ts` — `createHalEngine()` factory function
- **Public API**: `src/index.ts` — all exports developers consume
- **Example**: `example/server.ts` — minimal working server

## Architecture

Five mandatory layers (no cross-layer shortcuts, no circular deps). Declared in `layers.yaml` and enforced by `re-lint/no-cross-layer-import`, so a shortcut fails lint rather than review:

```
types → providers → infrastructure → orchestration → transport
```

| Layer | Path | Purpose |
|-------|------|---------|
| types | `src/types/` | Core interfaces: `AIProvider`, `SessionStore`, message protocol |
| providers | `src/providers/` | Bedrock (full), Vertex (full), OpenAI/Anthropic (stubs), Mock (built-in) |
| infrastructure | `src/infrastructure/` | Stores, prompt builder, thinking-tag parser |
| orchestration | `src/orchestration/` | `chatOrchestrator`, tool registry, context management |
| transport | `src/transport/` | Express app, WebSocket server, chat routes |

Pluggable interfaces: `AIProvider`, `SessionStore`, `WsAuthenticator`, `PromptStore`, `UsageStore`.

## Commands

```bash
npm run dev              # Hot-reload dev server: example/server.ts via tsx watch
npm run typecheck        # Type-check without emitting
npm test                 # Jest suite
npm run build            # Compile to dist/
npm run eslint           # Lint (zero-warning policy)
npm run prettier         # Format src/**/*.ts
npm run prettier:check   # Check formatting only
```

Pre-commit (run all):

```bash
npm run verify
```

## Code rules

- **TypeScript strict mode** — `strict: true` is non-negotiable; no `any` in public APIs
- **Type-only imports** — `import type { Foo } from '...'` for types
- **No `console.log`** — use `log` from `src/shared/logger.ts`
- **Single quotes**, semicolons required, line length 120 (Prettier)
- **Zero ESLint warnings** — all warnings are errors
- **Comments at most one line** — `re-lint/max-comment-lines` enforces this and does not exempt JSDoc, so a one-line `/** … */` passes but a `@param`/`@returns`/`@throws` block does not. Anything longer than one sentence belongs in `specs/`, `adrs/` or `docs/`, where it is searchable and linked. Tooling directives (`eslint-disable`, `@ts-expect-error`) are exempt, and an `eslint-disable` may carry its reason after `--`

## Testing

- Tests live next to source: `src/**/*.test.ts`
- Minimum 70% line coverage for new code; aim for >80% on modified files
- All public APIs need at least one test
- Use the built-in `MockProvider` for unit tests — avoid hitting real providers

## Protocol invariants

These rules enforce message ordering and must not be violated when adding providers, tools, or transport handlers:

- **Entry ordering**: `UserEntry` precedes `AssistantEntry`; tool results immediately follow the corresponding tool call; `ThinkingEntry` is committed before the assistant text entry begins
- **Append-only history**: session entries are immutable after commit — never mutate or delete existing entries
- **Atomic commit**: all entries within a single assistant response are committed before the next user message is processed
- **Provider immutability**: the provider selected at engine creation cannot change at runtime

## AIProvider full contract

Providers must implement **both** methods:

<!-- doc-block: src/types/ai.ts#AIProvider -->
```typescript
interface AIProvider {
  sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk>;
  generateStructured<T>(params: StructuredOutputParams<T>): Promise<T>;
}
```

`generateStructured` returns typed JSON for internal AI decisions (evaluation, classification, structured extraction) — it is not user-facing. Stub providers must throw `AIError` with a descriptive message; returning `null` or `undefined` silently breaks orchestration.

## Adding a provider

1. Create `src/providers/<name>/index.ts` implementing `AIProvider`
2. Return `AsyncGenerator<MessageChunk>` from `sendMessage`
3. Implement `generateStructured` (required — see contract above)
4. Handle rate-limiting; surface errors as `AIError` (not raw SDK errors)
5. Map tool calls to/from provider format in the provider layer
6. Export the config type and factory from `src/index.ts`
7. Update README provider table and `specs/hal-engine-providers/spec.md`

## Adding a tool

<!-- doc-block: none -- the registration call shape, with placeholder fields a reader fills in -->
```typescript
tools.register(
  {
    name: 'tool_name',
    description: '...',
    inputSchema: { type: 'object', properties: { ... }, required: [...] },
    promptInstructions?: string,   // appended to system prompt so the AI knows when/how to call this tool
    examplePrompts?: string[],     // surfaced to the client via ConnectedMessage.examplePrompts
  },
  async (input, context) => result
);
```

Tools receive a `ToolContext` with session, user, workspace. The return value is normalized:

| Return value | Effect |
|---|---|
| `string` or `{ content: string }` | Standard tool result returned to the AI |
| `{ entries: OutgoingMessage[] }` | Messages forwarded directly to the WebSocket client |
| `{ ..., suppressAssistantResponse: true }` | AI follow-up kept in session history but hidden from the client |

See `docs/adding-a-tool.md` and `specs/hal-engine-tool-responses/spec.md` for full details.

## OrchestratorHooks

Pass hooks to `createChatOrchestrator` (via `ChatOrchestratorOptions.hooks`) to intercept the message lifecycle:

<!-- doc-block: src/orchestration/chatOrchestrator.ts#OrchestratorHooks -->
```typescript
interface OrchestratorHooks {
  beforeSession?: (session: ChatSession) => Promise<void>;
  afterSession?: (session: ChatSession) => Promise<void>;
  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
  onError?: (session: ChatSession, error: Error) => Promise<void>;
}
```

Fire order: `beforeSession → beforeUserInput → afterUserInput → beforeModelResponse → [streaming] → afterModelResponse → afterSession`. The returned value matters for two of them: `beforeUserInput` rewrites the user message and `beforeModelResponse` replaces the system prompt. `afterSession` always fires, including on error. The block above is generated from the declaration, so the declaration order is not the fire order.

## Specs and ADRs

Normative specs live in `specs/<slug>/spec.md`, decision records in `adrs/`, and the repo-level system spec in `.specify/spec.md`. Research spikes are in `docs/spikes/`; `docs/` otherwise holds how-to guides.

Every spec under `specs/` opens with a header table whose `Status` row tracks its **test-citation coverage**, not how finished the feature is — a spec describing shipped behaviour still reads `Draft` until its statements cite tests. Read AGENTS.md § Spec Header Table and § Spec Test Links before adding or editing a spec.

## Commit format

```
<type>(<scope>): <subject>
```

Types: `feat`, `fix`, `refactor`, `test`, `docs`, `chore`, `perf`  
Scopes: `bedrock`, `vertex`, `openai`, `anthropic`, `mock`, `tools`, `orchestrator`, `transport`, `session`, `types`, `build`

Rules: imperative mood, no capital, no trailing period, subject ≤ 50 chars, reference issues in footer.

## Breaking changes

Must be discussed in an issue first, include a migration guide in the PR, bump MINOR version, and add a one-minor-version deprecation period where possible.

## ChatSession shape

`ChatSession` (in `src/types/session.ts`) uses `sessionId`, not `id`:

<!-- doc-block: src/types/session.ts#ChatSession -->
```typescript
interface ChatSession {
  sessionId: string;
  userId: string | number;
  entries: SessionEntry[];
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
  workspaceId?: string | number;
}
```

